#!/usr/bin/env python3"""Insert _serialize_element, _write_prompts_xml, update_base_prompts_from_xml, and --update-base into prompts.py."""from pathlib import Pathimport retarget = Path("bin/agent/prompts.py")raw = target.read_bytes()# 1. Insert _serialize_element + _write_prompts_xml after _prompt_node's "return prompt"serialize_block = b"""\rdef _serialize_element(elem: ET.Element, indent: str = "") -> str:\r    \"\"\"Serialize an Element to XML string with CDATA for value elements.\"\"\"\r    parts: list[str] = []\r    tag = elem.tag\r    attrs = ""\r    for k, v in elem.attrib.items():\r        attrs += f' {k}="{v}"'\r    children = list(elem)\r    has_children = len(children) > 0\r    if tag == "value" and elem.text:\r        parts.append(f"{indent}<{tag}{attrs}><![CDATA[{elem.text}]]></{tag}>")\r        return "".join(parts)\r    if not has_children and (elem.text is None or not elem.text.strip()):\r        parts.append(f"{indent}<{tag}{attrs} />")\r    elif not has_children:\r        parts.append(f"{indent}<{tag}{attrs}>{elem.text or ''}</{tag}>")\r    else:\r        parts.append(f"{indent}<{tag}{attrs}>")\r        for child in children:\r            parts.append("\\n")\r            parts.append(_serialize_element(child, indent + "  "))\r        parts.append(f"\\n{indent}</{tag}>")\r    return "".join(parts)\r\rdef _write_prompts_xml(tree: ET.ElementTree, target: Path) -> None:\r    \"\"\"Write the prompts XML tree to target using CDATA for value elements.\"\"\"\r    root = tree.getroot()\r    xml_str = '<?xml version=\"1.0\" encoding=\"UTF-8\"?>\\n'\r    xml_str += _serialize_element(root)\r    xml_str += "\\n"\r    target.write_text(xml_str, encoding=\"utf-8\")\r"""if b"def _serialize_element" not in raw:    anchor = b"    return prompt\r\n"    idx = raw.find(anchor)    if idx < 0:        print("ERROR: anchor 'return prompt' not found")        exit(1)    insert_pos = idx + len(anchor)    raw = raw[:insert_pos] + serialize_block + raw[insert_pos:]    print("OK: _serialize_element + _write_prompts_xml inserted")else:    print("SKIP: _serialize_element already exists")# 2. Insert update_base_prompts_from_xml before read_prompts_configupdate_block = b"""def update_base_prompts_from_xml(path: str | Path | None = None) -> Path:\r    \"\"\"Read XML <system> values and write them back as hardcoded defaults here.\"\"\"\r    target = Path(path).expanduser().resolve() if path else prompts_config_path()\r    if not target.exists():\r        raise FileNotFoundError(f\"prompts_config.xml not found at {target}\")\r    tree = _read_tree(target)\r    root = tree.getroot()\r    system, _project = _ensure_sections(root)\r    xml_prompts = _read_prompt_section(system)\r    if not xml_prompts:\r        return target\r    this_file = Path(__file__).resolve()\r    src = this_file.read_text(encoding=\"utf-8\")\r    lines: list[str] = [\"DEFAULT_SYSTEM_PROMPTS: Dict[str, str] = {\"]\r    seen: set[str] = set()\r    for key in DEFAULT_SYSTEM_PROMPTS:\r        seen.add(key)\r        value = xml_prompts.get(key, DEFAULT_SYSTEM_PROMPTS[key])\r        lines.append(f\"    {key!r}: {value!r},\")\r    for key, value in xml_prompts.items():\r        if key in seen:\r            continue\r        lines.append(f\"    {key!r}: {value!r},\")\r    lines.append(\"}\")\r    new_block = \"\\n\".join(lines)\r    pattern = re.compile(\r        r\"DEFAULT_SYSTEM_PROMPTS:\\s*Dict\\[str,\\s*str\\]\\s*=\\s*\\{.*?\\n\\}\",\r        re.DOTALL,\r    )\r    if not pattern.search(src):\r        raise RuntimeError(\"Could not locate DEFAULT_SYSTEM_PROMPTS dict in prompts.py source\")\r    updated = pattern.sub(new_block, src, count=1)\r    this_file.write_text(updated, encoding=\"utf-8\")\r    return target\r\r"""if b"def update_base_prompts_from_xml" not in raw:    anchor2 = b"def read_prompts_config("    idx2 = raw.find(anchor2)    if idx2 < 0:        print("ERROR: read_prompts_config not found")        exit(1)    raw = raw[:idx2] + update_block + raw[idx2:]    print("OK: update_base_prompts_from_xml inserted")else:    print("SKIP: update_base_prompts_from_xml already exists")# 3. Add --update-base CLI flagif b'"--update-base"' not in raw:    cli_anchor = b'    if "--reset-system" in args:\r\n        print(reset_system_prompts_to_defaults())\r\n        return 0'    cli_repl = b'    if "--update-base" in args:\r\n        print(update_base_prompts_from_xml())\r\n        return 0\r\n    if "--reset-system" in args:\r\n        print(reset_system_prompts_to_defaults())\r\n        return 0'    if cli_anchor in raw:        raw = raw.replace(cli_anchor, cli_repl, 1)        print("OK: --update-base CLI flag added")    else:        print("ERROR: CLI anchor not found")else:    print("SKIP: --update-base already exists")target.write_bytes(raw)print("Done, file written")